source="import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';\nimport {config} from './src/config.ts';import {render,validateVars} from './src/girls/template.ts';\nconst revision='bcc68c7e801ad65310f43f4a4ce09f05d3e3b4f7',after='2026-10-12T15:01:50Z';\nassert.equal(process.env.GIT_SHA,revision);assert.equal(process.env.V2_BUNDLES,'off');\nconst slugs=['briana-redd','fit-sid','kyla-yesenosky','mrs-callace','riley-mae-lewis','sania-mallory'];\nconst sb=async(route)=>{const r=await fetch(config.supabaseUrl+'/rest/v1/'+route,{headers:{apikey:config.supabaseKey,Authorization:'Bearer '+config.supabaseKey},signal:AbortSignal.timeout(12000)});assert(r.ok,'database read '+r.status);return r.json();};\nconst rows=await sb('clones?engine=eq.v2&status=eq.active&select=*');assert.deepEqual(rows.map(x=>x.slug).sort(),slugs);\nconst fleet=JSON.parse(fs.readFileSync(path.join(config.dataDir,'_fleet.json'),'utf8'));assert(Date.now()-Date.parse(fleet.at)<120000);\nconst results=[];\nfor(const c of rows){\n const rt=fleet.girls[c.slug];assert(rt?.status==='running');assert(Date.parse(rt.startedAt)>=Date.parse(after));\n assert.equal(c.v2_credits_enabled,false);assert.equal(c.tips_enabled,false);assert.equal(c.v2_memory_enabled,false);assert.equal(validateVars(c.v2_vars).length,0);\n const resp=await fetch('http://127.0.0.1:4300/api/girls/details?girl='+encodeURIComponent(c.slug),{signal:AbortSignal.timeout(15000)});assert(resp.ok);const d=await resp.json();assert.equal(d.errors.length,0);\n const displayed=d.parts.filter(x=>!x.optional).map(x=>x.text).join('');const actual=render(c.v2_vars);\n const content=x=>x.slice(x.indexOf('PHOTOS AND VIDEOS'),x.indexOf('HARD LIMITS, NEVER CROSSED'));\n assert(content(actual).length>100);assert.equal(content(displayed),content(actual));\n let telegram;\n if(['riley-mae-lewis','kyla-yesenosky','mrs-callace'].includes(c.slug)){\n  const tg=async(method,body={})=>{const r=await fetch('https://api.telegram.org/bot'+c.bot_token+'/'+method,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(12000)});const p=await r.json();if(!p.ok)return {ok:false,code:p.error_code};return {ok:true,result:p.result};};\n  const me=await tg('getMe');assert(me.ok);assert.equal(me.result.username,rt.botUsername);\n  const keys=new Set();let complete=false;\n  for(let offset=0;offset<10000;offset+=1000){const us=await sb('users?clone_id=eq.'+c.id+'&select=business_connection_id&business_connection_id=not.is.null&order=id&limit=1000&offset='+offset);for(const u of us)keys.add(u.business_connection_id);if(us.length<1000){complete=true;break;}}\n  assert(complete);const connections=[];\n  for(const key of keys){const bc=await tg('getBusinessConnection',{business_connection_id:key});const ownerMatch=c.business_username?String(bc.result?.user?.username??'').toLowerCase()===String(c.business_username).replace(/^@/,'').toLowerCase():null;connections.push({ok:bc.ok,code:bc.code,enabled:bc.result?.is_enabled,canReply:bc.result?.rights?.can_reply??bc.result?.can_reply,ownerMatch});}\n  telegram={bot:me.result.username,connections,hasEnabledReplyConnection:connections.some(b=>b.ok&&b.enabled&&b.canReply&&b.ownerMatch!==false)};\n  assert(telegram.hasEnabledReplyConnection,c.slug+' has no verified enabled reply connection');\n }\n results.push({creator:c.slug,running:true,startedAt:rt.startedAt,liveMonitorPolicyMatches:true,credits:false,tips:false,memory:false,vision:c.vision_model,photoOverride:c.photo_vision_model??null,...(telegram?{telegram}:{})});\n}\nconst observations=[];\nfor(const slug of ['riley-mae-lewis','kyla-yesenosky']){\n const p=path.join(config.logDir,slug,'requests.jsonl');if(!fs.existsSync(p)){observations.push({creator:slug,turns:[]});continue;}\n const fd=fs.openSync(p,'r'),size=fs.fstatSync(fd).size,start=Math.max(0,size-2000000),b=Buffer.alloc(size-start);fs.readSync(fd,b,0,b.length,start);fs.closeSync(fd);\n const lines=b.toString('utf8').split('\\n');if(start)lines.shift();\n const turns=[];for(const line of lines){let t;try{t=JSON.parse(line);}catch{continue;}if(Date.parse(t.ts)<Date.parse(after)||String(t.chatId)!=='6814483810')continue;turns.push({at:t.ts,route:t.route,selected:t.selectedMedia?.key??null,acknowledgedMedia:t.media?.key??null,mediaOutcome:t.delivery?.media?.state??t.delivery?.media?.status??null,photoIntent:t.photoRequest?.intent??null});}\n observations.push({creator:slug,turns:turns.slice(-10)});\n}\nconst [trashy]=await sb('clones?id=eq.3484f7d9-0cda-4f52-84de-e104c238ce5e&select=engine,status');assert.equal(trashy.engine,'live');\nconsole.log(JSON.stringify({checkedAt:new Date().toISOString(),revision,model:config.model,providerOrder:config.providerOrder,fleetAt:fleet.at,results,testerPostReleaseObservations:observations,trashy,telegramSends:0,modelCalls:0}));\n"
